1	import { lazy, Suspense } from "react";
2	import { Toaster as Sonner } from "@/components/ui/sonner";
3	import { TooltipProvider } from "@/components/ui/tooltip";
4	import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
5	import { BrowserRouter, Routes, Route } from "react-router-dom";
6	import { AuthProvider, useAuth } from "@/hooks/useAuth";
7	import { useFeatureFlag } from "@/hooks/useFeatureFlags";
8	import { ProtectedRoute, AdminRoute } from "@/components/ProtectedRoute";
9	import { ThemeProvider } from "@/components/ThemeProvider";
10	import MaintenancePage from "@/components/MaintenancePage";
11	import SeoHead from "@/components/SeoHead";
12	import ChatWidget from "@/components/ChatWidget";
13	
14	// Lazy-loaded route components for code splitting
15	const Index = lazy(() => import("./pages/Index"));
16	const Auth = lazy(() => import("./pages/Auth"));
17	const Admin = lazy(() => import("./pages/Admin"));
18	const Settings = lazy(() => import("./pages/Settings"));
19	const Profile = lazy(() => import("./pages/Profile"));
20	const Billing = lazy(() => import("./pages/Billing"));
21	const NotFound = lazy(() => import("./pages/NotFound"));
22	const PaymentCallback = lazy(() => import("./pages/PaymentCallback"));
23	const BookDemo = lazy(() => import("./pages/BookDemo"));
24	const RequestFeature = lazy(() => import("./pages/RequestFeature"));
25	const Changelog = lazy(() => import("./pages/Changelog"));
26	const Apply = lazy(() => import("./pages/Apply"));
27	const LandingPage = lazy(() => import("@/components/LandingPage"));
28	
29	const queryClient = new QueryClient();
30	
31	const PageLoader = () => null;
32	
33	const MaintenanceGate = ({ children }: { children: React.ReactNode }) => {
34	  const { enabled, isLoading: flagLoading } = useFeatureFlag("maintenance_mode");
35	  const { isAdmin, loading } = useAuth();
36	
37	  // Don't block rendering while loading — only gate when we know maintenance is on
38	  if (!loading && !flagLoading && enabled && !isAdmin) return <MaintenancePage />;
39	  return <>{children}</>;
40	};
41	
42	const RootRoute = () => {
43	  const { user, loading } = useAuth();
44	  if (loading) return <PageLoader />;
45	  return user ? <Index /> : <LandingPage />;
46	};
47	
48	const App = () => (
49	  <QueryClientProvider client={queryClient}>
50	    <ThemeProvider attribute="class" defaultTheme="light" storageKey="rankora-theme">
51	      <AuthProvider>
52	        <TooltipProvider>
53	          <Sonner />
54	          <BrowserRouter>
55	            <SeoHead />
56	            <Suspense fallback={<PageLoader />}>
57	              <Routes>
58	                {/* Public apply page — outside MaintenanceGate so candidates can always apply */}
59	                <Route path="/apply/:jobId" element={<Apply />} />
60	                <Route path="*" element={
61	                  <MaintenanceGate>
62	                    <Routes>
63	                      <Route path="/auth" element={<Auth />} />
64	                      <Route path="/" element={<RootRoute />} />
65	                      <Route path="/jobs" element={<ProtectedRoute><Index /></ProtectedRoute>} />
66	                      <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
67	                      <Route path="/billing" element={<ProtectedRoute><Billing /></ProtectedRoute>} />
68	                      <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
69	                      <Route path="/admin" element={<AdminRoute><Admin /></AdminRoute>} />
70	                      <Route path="/book-demo" element={<BookDemo />} />
71	                      <Route path="/request-feature" element={<RequestFeature />} />
72	                      <Route path="/changelog" element={<Changelog />} />
73	                      <Route path="/payment/callback" element={<PaymentCallback />} />
74	                      <Route path="*" element={<NotFound />} />
75	                    </Routes>
76	                  </MaintenanceGate>
77	                } />
78	              </Routes>
79	            </Suspense>
80	            <ChatWidget />
81	          </BrowserRouter>
82	        </TooltipProvider>
83	      </AuthProvider>
84	    </ThemeProvider>
85	  </QueryClientProvider>
86	);
87	
88	export default App;
89

1	// Sentry must be imported FIRST — before any other imports
2	import "./instrument";
3	
4	import { createRoot } from "react-dom/client";
5	import * as Sentry from "@sentry/react";
6	import App from "./App.tsx";
7	import "./index.css";
8	import { logClientError } from "./lib/logClientError";
9	
10	// Global uncaught JS errors — log to both Sentry + Supabase
11	window.onerror = (message, source, lineno, colno, error) => {
12	  const src = source
13	    ? new URL(source, window.location.href).pathname.split("/").pop() ?? "frontend"
14	    : "frontend";
15	  logClientError("UnhandledError", src, String(message), error?.stack, { source, lineno, colno });
16	};
17	
18	// Global unhandled promise rejections
19	window.addEventListener("unhandledrejection", (event) => {
20	  const reason = event.reason;
21	  const message = reason instanceof Error ? reason.message : String(reason ?? "Unhandled rejection");
22	  const stack = reason instanceof Error ? reason.stack : undefined;
23	  logClientError("UnhandledRejection", "frontend", message, stack);
24	});
25	
26	createRoot(document.getElementById("root")!).render(
27	  <Sentry.ErrorBoundary fallback={<p className="flex items-center justify-center min-h-screen text-muted-foreground">Something went wrong. Please refresh the page.</p>}>
28	    <App />
29	  </Sentry.ErrorBoundary>,
30	);
