1	import { useState, useCallback, useRef, useEffect, useMemo } from "react";
2	import { useAuth } from "@/hooks/useAuth";
3	import { usePlatformConfig } from "@/hooks/usePlatformConfig";
4	import { validateRanking } from "@/lib/validateRanking";
5	import { findDuplicateResumeIds } from "@/lib/deduplicateCandidates";
6	import { supabase } from "@/integrations/supabase/client";
7	import { Button } from "@/components/ui/button";
8	import { Textarea } from "@/components/ui/textarea";
9	import { Checkbox } from "@/components/ui/checkbox";
10	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
11	import { Badge } from "@/components/ui/badge";
12	import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
13	import { Progress } from "@/components/ui/progress";
14	import { Skeleton } from "@/components/ui/skeleton";
15	import {
16	  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
17	  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle
18	} from "@/components/ui/alert-dialog";
19	import { toast } from "sonner";
20	import {
21	  Upload, Copy, Loader2, FileText,
22	  AlertTriangle, X, Trash2, RefreshCw, CheckCircle2, FileSpreadsheet,
23	  ListChecks, BarChart2, ArrowRight, Clock, Users, Star, Mail,
24	  Archive, ArchiveRestore, FolderOpen, PenLine, Pencil, Wallet, ScanLine, Zap,
25	  ChevronLeft, Link2, ClipboardCheck,
26	} from "lucide-react";
27	import { Link } from "react-router-dom";
28	import { exportToCSV } from "@/lib/csvExport";
29	import CandidateRow from "@/components/CandidateRow";
30	import CandidateDetailSheet from "@/components/CandidateDetailSheet";
31	import JDRewriteDialog from "@/components/JDRewriteDialog";
32	import ConfidenceReport from "@/components/ConfidenceReport";
33	import type { PastJob, Result, ExistingResume } from "@/pages/Index";
34	import { useStages, useUpdateStage, useStageSummary, STAGE_ORDER, type HiringStage } from "@/hooks/useStageTracker";
35	import ApplicationsTab from "@/components/ApplicationsTab";
36	
37	interface JobDetailViewProps {
38	  selectedJobId: string | null;
39	  selectedJob: PastJob | null;
40	  results: Result[];
41	  setResults: (results: Result[] | ((prev: Result[]) => Result[])) => void;
42	  existingResumes: ExistingResume[];
43	  setExistingResumes: (resumes: ExistingResume[] | ((prev: ExistingResume[]) => ExistingResume[])) => void;
44	  onJobCreated: (job: PastJob) => void;
45	  onAuthRequired: () => void;
46	  onJobUpdated?: (jobId: string, updates: Partial<PastJob>) => void;
47	  isAuthenticated?: boolean;
48	  pastJobs?: PastJob[];
49	  onBack?: () => void;
50	}
51	
52	interface UploadedFile {
53	  file: File;
54	  name: string;
55	}
56	
57	const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
58	
59	const JobDetailView = ({
60	  selectedJobId,
61	  selectedJob,
62	  results,
63	  setResults,
64	  existingResumes,
65	  setExistingResumes,
66	  onJobCreated,
67	  onAuthRequired,
68	  onJobUpdated,
69	  isAuthenticated = true,
70	  pastJobs = [],
71	  onBack,
72	}: JobDetailViewProps) => {
73	  const { user, profile, refreshProfile } = useAuth();
74	  const { data: config } = usePlatformConfig();
75	
76	  const [jobTitle, setJobTitle] = useState("");
77	  const [jobDescription, setJobDescription] = useState("");
78	  const [files, setFiles] = useState<UploadedFile[]>([]);
79	  const [selectedFileIndexes, setSelectedFileIndexes] = useState<Set<number>>(new Set());
80	  const [ranking, setRanking] = useState(false);
81	  const [rankingProgress, setRankingProgress] = useState(0);
82	  const [scoredCount, setScoredCount] = useState(0);
83	  const [totalToScore, setTotalToScore] = useState(0);
84	  const [selectedCandidateId, setSelectedCandidateId] = useState<string | null>(null);
85	  const [dragOver, setDragOver] = useState(false);
86	  const [rankingError, setRankingError] = useState<{ type: "credits" | "rate_limit" | "generic"; message: string } | null>(null);
87	  const [validationErrors, setValidationErrors] = useState<string[]>([]);
88	  const [selectedResumes, setSelectedResumes] = useState<Set<string>>(new Set());
89	  const [deleteConfirm, setDeleteConfirm] = useState<{type: "single" | "bulk"; resumeId?: string; filePath?: string | null;} | null>(null);
90	  const [deleting, setDeleting] = useState(false);
91	  const [analyzingJd, setAnalyzingJd] = useState(false);
92	  const [dismissedResumes, setDismissedResumes] = useState<Set<string>>(() => new Set());
93	  const [showArchived, setShowArchived] = useState(false);
94	  const [stageFilter, setStageFilter] = useState<HiringStage | null>(null);
95	  const [jdRewriteOpen, setJdRewriteOpen] = useState(false);
96	  const [stuckJobDetected, setStuckJobDetected] = useState(false);
97	  const [retrying, setRetrying] = useState(false);
98	  const [editingJd, setEditingJd] = useState(false);
99	  const [editedJdText, setEditedJdText] = useState("");
100	  const [confirmEditJdOpen, setConfirmEditJdOpen] = useState(false);
101	  const [activeTab, setActiveTab] = useState<"resumes" | "applications">("resumes");
102	
103	  const resultsRef = useRef<HTMLDivElement>(null);
104	  const rankingFilesRef = useRef<Set<string>>(new Set());
105	  const rankingLockRef = useRef(false);
106	  const activeJobRef = useRef<string | null>(selectedJobId);
107	  const maxResumes = config?.max_resumes_per_job ?? 10;
108	  const maxFileSizeMb = config?.max_file_size_mb ?? 5;
109	
110	  const isNewJobMode = selectedJobId === null;
111	  const isExistingJob = selectedJobId !== null && selectedJob !== null;
112	
113	  // Detect duplicate candidates across results (by name/email)
114	  const duplicateResumeIds = useMemo(() => findDuplicateResumeIds(results), [results]);
115	
116	  // Hiring Stage Tracker
117	  const { data: stages } = useStages(selectedJobId);
118	  const updateStageMutation = useUpdateStage();
119	  const stageSummary = useStageSummary(selectedJobId);
120	  const stageMap = new Map((stages ?? []).map((s) => [s.resume_id, s]));
121	
122	  const handleStageChange = (resumeId: string, newStage: HiringStage) => {
123	    if (!selectedJobId) return;
124	    const current = stageMap.get(resumeId);
125	    updateStageMutation.mutate({
126	      resumeId,
127	      jobId: selectedJobId,
128	      newStage,
129	      currentStage: current?.stage,
130	    });
131	  };
132	
133	  const formatCandidateName = (filename: string) => {
134	    const name = filename.replace(/\.\w+$/, "");
135	    if (UUID_REGEX.test(name)) return `Resume ${name.slice(0, 6).toUpperCase()}`;
136	    return name.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
137	  };
138	
139	  // Merge unranked resumes
140	  const resultResumeIds = new Set(results.map((r) => r.resume_id));
141	  const pendingResumes: Result[] = existingResumes
142	    .filter((r) => !resultResumeIds.has(r.id))
143	    .map((r) => ({
144	      id: `pending-${r.id}`,
145	      resume_id: r.id,
146	      overall_score: 0,
147	      missing_skills: [], summary: null, interview_questions: null,
148	      filename: r.filename, file_path: r.file_path, candidate_name: r.candidate_name,
149	      pending: true,
150	    }));
151	  const allResults = [...results, ...pendingResumes];
152	
153	  // Selection helpers
154	  const toggleSelectResume = (resumeId: string) => {
155	    setSelectedResumes((prev) => {
156	      const next = new Set(prev);
157	      if (next.has(resumeId)) next.delete(resumeId); else next.add(resumeId);
158	      return next;
159	    });
160	  };
161	  const toggleSelectAll = () => {
162	    if (selectedResumes.size === allResults.length) setSelectedResumes(new Set());
163	    else setSelectedResumes(new Set(allResults.map((r) => r.resume_id)));
164	  };
165	
166	  // Delete logic
167	  const deleteResume = async (resumeId: string, filePath: string | null) => {
168	    if (filePath) await supabase.storage.from("resumes").remove([filePath]);
169	    await supabase.from("results").delete().eq("resume_id", resumeId);
170	    await supabase.from("resumes").delete().eq("id", resumeId);
171	    setResults((prev: Result[]) => prev.filter((r) => r.resume_id !== resumeId));
172	    setExistingResumes((prev: ExistingResume[]) => prev.filter((r) => r.id !== resumeId));
173	    setSelectedResumes((prev) => { const next = new Set(prev); next.delete(resumeId); return next; });
174	  };
175	
176	  const handleDeleteConfirm = async () => {
177	    if (!deleteConfirm) return;
178	    setDeleting(true);
179	    try {
180	      if (deleteConfirm.type === "single" && deleteConfirm.resumeId) {
181	        await deleteResume(deleteConfirm.resumeId, deleteConfirm.filePath ?? null);
182	        toast.success("Resume deleted");
183	      } else if (deleteConfirm.type === "bulk") {
184	        const toDelete = allResults.filter((r) => selectedResumes.has(r.resume_id));
185	        for (const r of toDelete) await deleteResume(r.resume_id, r.file_path);
186	        toast.success(`${toDelete.length} resume(s) deleted`);
187	      }
188	    } catch { toast.error("Failed to delete"); }
189	    finally { setDeleting(false); setDeleteConfirm(null); }
190	  };
191	
192	  // File handling
193	  const handleFileDrop = useCallback((e: React.DragEvent) => {
194	    e.preventDefault(); setDragOver(false);
195	    const dropped = Array.from(e.dataTransfer.files).filter(
196	      (f) => f.type === "application/pdf" || f.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
197	    );
198	    addFiles(dropped);
199	  }, [files, maxResumes, maxFileSizeMb]);
200	
201	  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
202	    if (e.target.files) addFiles(Array.from(e.target.files));
203	  };
204	
205	  const addFiles = (newFiles: File[]) => {
206	    const currentCount = isExistingJob ? existingResumes.length + files.length : files.length;
207	    // Build set of already-known filenames (pending uploads + existing resumes for this job)
208	    const existingNames = new Set([
209	      ...files.map(f => f.name.toLowerCase()),
210	      ...existingResumes.map(r => r.filename.toLowerCase()),
211	    ]);
212	    const duplicates: string[] = [];
213	    const valid = newFiles.filter((f) => {
214	      if (f.size > maxFileSizeMb * 1024 * 1024) { toast.error(`${f.name} exceeds ${maxFileSizeMb}MB limit`); return false; }
215	      if (existingNames.has(f.name.toLowerCase())) { duplicates.push(f.name); return false; }
216	      existingNames.add(f.name.toLowerCase()); // prevent dupes within the same batch
217	      return true;
218	    });
219	    if (duplicates.length > 0) {
220	      toast.error(`Duplicate resume${duplicates.length > 1 ? "s" : ""} skipped: ${duplicates.join(", ")}`);
221	    }
222	    const remaining = maxResumes - currentCount;
223	    if (valid.length > remaining) toast.error(`Max ${maxResumes} resumes per job`);
224	    const toAdd = valid.slice(0, Math.max(0, remaining)).map((f) => ({ file: f, name: f.name }));
225	    setFiles((prev) => [...prev, ...toAdd]);
226	  };
227	
228	  const removeFile = (index: number) => setFiles((prev) => prev.filter((_, i) => i !== index));
229	  const selectCandidate = (id: string) => {
230	    setSelectedCandidateId((prev) => prev === id ? null : id);
231	  };
232	
233	  const copyInboxEmail = () => {
234	    if (profile?.inbox_email) { navigator.clipboard.writeText(profile.inbox_email); toast.success("Inbox email copied!"); }
235	  };
236	
237	  const validate = (): string[] => {
238	    const filesToCheck = files.filter(f => !rankingFilesRef.current.has(f.name));
239	    return validateRanking({
240	      isNewJobMode,
241	      jobDescription,
242	      fileCount: filesToCheck.length,
243	      subscriptionCredits: profile?.subscription_credits ?? 0,
244	      topupCredits: profile?.topup_credits ?? 0,
245	      totalCredits: profile?.credits ?? 0,
246	      maxResumes,
247	      isAuthenticated: !!user,
248	    });
249	  };
250	
251	  // ── Analyze JD ──────────────────────────────────────────────
252	  const analyzeJd = async (jobId: string) => {
253	    setAnalyzingJd(true);
254	    try {
255	      // Refresh auth session before invoking to prevent stale token errors
256	      await supabase.auth.refreshSession();
257	
258	      const { data, error: invokeError } = await supabase.functions.invoke("analyze-jd", {
259	        body: { job_id: jobId },
260	      });
261	      if (invokeError) throw new Error(invokeError.message || "JD analysis failed");
262	      if (data?.error) throw new Error(data.error);
263	      if (onJobUpdated) {
264	        onJobUpdated(jobId, {
265	          jd_analysis_json: data.jd_analysis,
266	          dynamic_weights_json: data.dynamic_weights,
267	        });
268	      }
269	      return data;
270	    } catch (err: any) {
271	      toast.error(err.message || "JD analysis failed");
272	      throw err;
273	    } finally {
274	      setAnalyzingJd(false);
275	    }
276	  };
277	
278	  // ── Reset all transient state when switching jobs ──
279	  useEffect(() => {
280	    activeJobRef.current = selectedJobId;
281	    setFiles([]);
282	    setRanking(false);
283	    setRankingProgress(0);
284	    setScoredCount(0);
285	    setTotalToScore(0);
286	    setSelectedCandidateId(null);
287	    setValidationErrors([]);
288	    setRankingError(null);
289	    setAnalyzingJd(false);
290	    setStuckJobDetected(false);
291	    setSelectedResumes(new Set());
292	    setShowArchived(false);
293	    setStageFilter(null);
294	    setEditingJd(false);
295	    setEditedJdText("");
296	    setActiveTab("resumes");
297	    rankingFilesRef.current = new Set();
298	    autoRankTriggered.current = false;
299	    if (selectedJobId) {
300	      try {
301	        const stored = localStorage.getItem(`dismissed_${selectedJobId}`);
302	        if (stored) {
303	          setDismissedResumes(new Set(JSON.parse(stored) as string[]));
304	        } else {
305	          setDismissedResumes(new Set());
306	        }
307	      } catch {
308	        setDismissedResumes(new Set());
309	      }
310	    } else {
311	      setDismissedResumes(new Set());
312	    }
313	  }, [selectedJobId]);
314	
315	  // ── Auto-rank (only if user has auto_rank_enabled) ──────────
316	  const autoRankTriggered = useRef(false);
317	  useEffect(() => {
318	    if (profile?.auto_rank_enabled === false) return;
319	    const unrankedFiles = files.filter(f => !rankingFilesRef.current.has(f.name));
320	    if (unrankedFiles.length > 0 && !ranking && !autoRankTriggered.current) {
321	      if (isNewJobMode && !jobDescription.trim()) return;
322	      autoRankTriggered.current = true;
323	      handleRankClick();
324	    }
325	    if (files.length === 0 && !ranking) autoRankTriggered.current = false;
326	  }, [files, ranking, isNewJobMode, jobDescription]);
327	
328	  // ── Create job explicitly ────────────────────────────────
329	  const [creatingJob, setCreatingJob] = useState(false);
330	  const handleCreateJob = async () => {
331	    if (!user) { onAuthRequired(); return; }
332	    if (!jobDescription.trim()) { toast.error("Please enter a job description"); return; }
333	    setCreatingJob(true);
334	    try {
335	      const title = jobTitle.trim() || (() => {
336	        const firstLine = jobDescription.trim().split("\n")[0].trim();
337	        return firstLine.slice(0, 50).trim() || `Job - ${new Date().toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}`;
338	      })();
339	      const { data: job, error } = await supabase
340	        .from("jobs")
341	        .insert({ user_id: user.id, job_description: jobDescription, status: "pending", title } as any)
342	        .select("id, inbox_email")
343	        .single();
344	      if (error || !job) throw new Error(error?.message || "Failed to create job");
345	      onJobCreated({
346	        id: job.id, title, job_description: jobDescription, status: "pending",
347	        created_at: new Date().toISOString(), resume_count: 0,
348	        jd_analysis_json: null, dynamic_weights_json: null, inbox_email: job.inbox_email ?? null,
349	      });
350	      setJobTitle("");
351	      setJobDescription("");
352	      toast.success("Job created");
353	    } catch (err: any) {
354	      toast.error(err.message || "Failed to create job");
355	    } finally {
356	      setCreatingJob(false);
357	    }
358	  };
359	
360	  const handleRankingError = (err: any) => {
361	    const msg: string = err?.message || "Ranking failed.";
362	    if (msg.includes("Unauthorized") || msg.includes("No auth") || err?.status === 401) {
363	      setRankingError({ type: "generic", message: "Your session has expired. Please refresh the page and try again." });
364	      toast.error("Session expired. Please refresh and try again.");
365	    } else if (msg.includes("Insufficient credits") || err?.status === 402) {
366	      setRankingError({ type: "credits", message: "You don't have enough credits to rank these resumes." });
367	    } else if (msg.includes("Rate limit") || err?.status === 429) {
368	      setRankingError({ type: "rate_limit", message: "Too many jobs in a short time. Please wait a minute and try again." });
369	    } else {
370	      setRankingError({ type: "generic", message: msg });
371	      toast.error(msg);
372	    }
373	  };
374	
375	  const handleRankClick = () => {
376	    if (ranking || rankingLockRef.current) return;
377	    if (!user) { onAuthRequired(); return; }
378	    rankingLockRef.current = true;
379	    setRankingError(null);
380	    const errors = validate();
381	    if (errors.length > 0) {
382	      setValidationErrors(errors);
383	      rankingLockRef.current = false;
384	      return;
385	    }
386	    setValidationErrors(errors);
387	    if (isExistingJob) handleRankExisting(); else handleRankNew();
388	  };
389	
390	  const handleRankNew = async () => {
391	    if (!user) return;
