62	    queryKey: ["apply-job-info", jobId],
63	    queryFn: async () => {
64	      if (!jobId) return null;
65	      const { data, error } = await supabase.rpc("get_job_apply_info", {
66	        p_job_id: jobId,
67	      });
68	      if (error) throw new Error(error.message);
69	      if (!data || (Array.isArray(data) && data.length === 0)) return null;
70	      const row = Array.isArray(data) ? data[0] : data;
71	      return row as JobInfo;
