3	// Client-side dedup: skip if same error logged within the last 30 seconds
4	const recentErrors = new Map<string, number>();
5	
6	/**
7	 * Log a frontend runtime error to system_error_logs via the log-client-error edge function.
8	 * Safe to call from anywhere — never throws.
9	 */
10	export async function logClientError(
11	  errorType: string,
12	  source: string,
13	  message: string,
14	  stack?: string,
15	  extra?: Record<string, unknown>,
16	): Promise<void> {
17	  try {
18	    const key = `${source}:${message.slice(0, 120)}`;
19	    const now = Date.now();
20	    if ((recentErrors.get(key) ?? 0) > now - 30_000) return; // dedup
21	    recentErrors.set(key, now);
22	
23	    // Clean up old entries to avoid memory leak
24	    if (recentErrors.size > 100) {
25	      const cutoff = now - 60_000;
26	      for (const [k, t] of recentErrors.entries()) {
27	        if (t < cutoff) recentErrors.delete(k);
28	      }
29	    }
30	
31	    const { data: { user } } = await supabase.auth.getUser();
32	
33	    await supabase.functions.invoke("log-client-error", {
34	      body: {
35	        error_type: errorType,
36	        function_name: source,
37	        severity: "warning",
38	        error_message: message,
39	        error_stack: stack,
40	        context_json: extra ?? {},
41	        user_id: user?.id ?? null,
42	      },
43	    });
44	  } catch {
45	    // Never throw from an error logger
46	  }
47	}
