8	    queryKey: ["chat_widget_config"],
9	    queryFn: async () => {
10	      const { data, error } = await supabase
11	        .from("platform_config")
12	        .select("chat_widget_enabled, chat_widget_code")
13	        .limit(1)
14	        .single();
15	      if (error) return null;
16	      return data as { chat_widget_enabled: boolean; chat_widget_code: string } | null;
17	    },
18	    staleTime: 5 * 60 * 1000,
19	  });
20	
21	  useEffect(() => {
22	    const containerId = "rankora-chat-widget";
23	
24	    // Clean up any previous widget
25	    const existing = document.getElementById(containerId);
26	    if (existing) existing.remove();
27	
28	    if (!data?.chat_widget_enabled || !data?.chat_widget_code?.trim()) return;
29	
30	    // Create a container and inject the embed code
31	    const container = document.createElement("div");
32	    container.id = containerId;
33	    document.body.appendChild(container);
34	
35	    // Sanitize embed code — allow external scripts (src-based) but strip inline script content
36	    const sanitized = DOMPurify.sanitize(data.chat_widget_code, {
37	      ADD_TAGS: ["script", "iframe"],
38	      ADD_ATTR: ["src", "async", "defer", "allow", "allowfullscreen", "frameborder", "scrolling"],
39	      FORCE_BODY: true,
40	    });
41	
42	    // Parse and execute scripts from the sanitized embed code
43	    const temp = document.createElement("div");
44	    temp.innerHTML = sanitized;
45	
46	    // Move non-script nodes and re-create script tags to execute them
47	    Array.from(temp.childNodes).forEach((node) => {
48	      if (node instanceof HTMLScriptElement) {
49	        const script = document.createElement("script");
50	        // Only allow scripts with external src — strip inline script content for safety
51	        if (node.src) {
52	          script.src = node.src;
53	          if (node.async) script.async = true;
54	          if (node.defer) script.defer = true;
55	          Array.from(node.attributes).forEach((attr) => {
56	            if (!["src", "async", "defer"].includes(attr.name)) {
57	              script.setAttribute(attr.name, attr.value);
58	            }
59	          });
60	          container.appendChild(script);
61	        }
62	      } else {
63	        container.appendChild(node.cloneNode(true));
64	      }
65	    });
66	
67	    return () => {
68	      const el = document.getElementById(containerId);
69	      if (el) el.remove();
70	    };
71	  }, [data?.chat_widget_enabled, data?.chat_widget_code]);
72	
73	  return null;
74	};
